/**
 * Unblock Resolved Dependencies — postJSAction for unblock_resolved_dependencies agent.
 *
 * Runs on every SM cycle for each ticket in "Blocked" status.
 * - Reads issuelinks to find all "is blocked by" dependencies (inwardIssue with Blocks link type).
 * - If all blockers are in a terminal status (Done, Merged, Passed, Closed, Irrelevant)
 *   or the blocker was deleted (inwardIssue === null), moves the ticket to Backlog.
 * - Otherwise leaves the ticket in Blocked.
 */

const configLoader = require('./configLoader.js');
const tokenUsageComment = require('./common/tokenUsageComment.js');
const trackersModule = require('./common/trackers.js');

function isResolved(blocker, terminalStatuses) {
    // Deleted ticket — no inwardIssue object at all
    if (!blocker) return true;

    var statusName = blocker.fields && blocker.fields.status && blocker.fields.status.name;
    if (!statusName) return false;

    return terminalStatuses.indexOf(statusName) !== -1;
}

// ── pure parse/build/decide helpers (CRAP gate: each ≤ 8) ───────────────────

// Ticket key from the dmtools params shape.
function ticketKeyOf(params) {
    return params.ticket && params.ticket.key;
}

// Inward blockers of the current ticket: links of type Blocks carrying an inwardIssue.
function blockersOf(links) {
    var blockers = [];
    for (var i = 0; i < links.length; i++) {
        var link = links[i];
        // inwardIssue means: current ticket is blocked by the inwardIssue
        if (link.inwardIssue && link.type && link.type.name === 'Blocks') {
            blockers.push(link.inwardIssue);
        }
    }
    return blockers;
}

function issuelinksOf(ticket) {
    return (ticket && ticket.fields && ticket.fields.issuelinks) || [];
}

// Terminal statuses that count a blocker as resolved ('Closed' kept as a
// literal for backward compatibility — not part of STATUSES/config).
function terminalStatusesOf(jiraConfig) {
    return [
        jiraConfig.statuses.DONE,
        jiraConfig.statuses.MERGED,
        jiraConfig.statuses.PASSED,
        jiraConfig.statuses.IRRELEVANT,
        'Closed'
    ].filter(Boolean);
}

// Split blockers into resolved (logged) and unresolved {key,status} entries.
function classifyBlockers(blockers, terminalStatuses) {
    var unresolved = [];
    for (var j = 0; j < blockers.length; j++) {
        var b = blockers[j];
        var bKey = b.key || '?';
        var bStatus = b.fields && b.fields.status && b.fields.status.name || 'Unknown';
        if (isResolved(b, terminalStatuses)) {
            console.log('  Blocker', bKey, 'is resolved (', bStatus, ')');
        } else {
            console.log('  Blocker', bKey, 'is NOT resolved (', bStatus, ')');
            unresolved.push({ key: bKey, status: bStatus });
        }
    }
    return unresolved;
}

function emptyToNull(list) {
    return list.length > 0 ? list : null;
}

function unresolvedKeysText(unresolved) {
    return unresolved.map(function(u) { return u.key; }).join(', ');
}

function moveFailed(error) {
    return { success: false, action: 'move_failed', error: error.toString() };
}

// '- KEY (STATUS)' lines describing the resolved blockers.
function resolvedKeysText(blockers) {
    return blockers.map(function(b) {
        return b.key + ' (' + (b.fields && b.fields.status && b.fields.status.name || '?') + ')';
    }).join(', ');
}

function unblockComment(blockers) {
    var resolvedKeys = resolvedKeysText(blockers);
    return 'h3. ✅ Auto-unblocked — All Dependencies Resolved\n\n' +
            'All *' + blockers.length + '* blocker(s) are now in a terminal status:\n' +
            resolvedKeys.split(', ').map(function(k) { return '- ' + k; }).join('\n') + '\n\n' +
            'Automatically moved back to *Backlog* for re-processing.';
}

// Config + tracker + ticket fetch + blocker classification for one check run.
function checkBlockers(params, ticketKey) {
    var projectConfig = configLoader.loadProjectConfig(params.jobParams || params);
    var tracker = trackersModule.createTracker(projectConfig, (params.jobParams && params.jobParams.customParams) || {});

    console.log('=== Unblock resolved dependencies check for', ticketKey, '===');

    var ticket;
    try {
        ticket = tracker.getIssue(ticketKey, ['issuelinks']);
    } catch (e) {
        console.warn('Failed to fetch ticket details:', e.message || e);
        return { error: { success: false, action: 'fetch_failed', error: e.toString() } };
    }

    var blockers = blockersOf(issuelinksOf(ticket));
    console.log('Found', blockers.length, 'blocker(s) for', ticketKey);

    return {
        tracker: tracker,
        backlogStatus: projectConfig.jira.statuses.BACKLOG,
        blockers: blockers,
        unresolved: blockers.length === 0 ? null : emptyToNull(classifyBlockers(blockers, terminalStatusesOf(projectConfig.jira)))
    };
}

// No blockers at all: move + comment share one try — a comment failure
// surfaces as move_failed exactly as before.
function unblockWithoutBlockers(check, ticketKey) {
    console.log('No active blockers found — moving', ticketKey, 'to Backlog');
    try {
        check.tracker.moveToStatus(ticketKey, check.backlogStatus);
        check.tracker.postComment(ticketKey, 'h3. ✅ Auto-unblocked — No Active Blockers\n\n' +
                'This ticket was in *Blocked* status but no active "is blocked by" dependencies were found.\n\n' +
                'Automatically moved back to *Backlog* for re-processing.');
        console.log('✅ Moved', ticketKey, 'to Backlog (no blockers)');
        return { success: true, action: 'moved_to_backlog_no_blockers', ticketKey: ticketKey };
    } catch (e) {
        console.warn('Failed to move ticket to Backlog:', e.message || e);
        return moveFailed(e);
    }
}

// All blockers resolved: move first (failure aborts), then comment and token
// usage postings — each failure-tolerant, never blocking the unblock.
function unblockAllResolved(check, ticketKey, params) {
    console.log('All', check.blockers.length, 'blocker(s) resolved — moving', ticketKey, 'to Backlog');
    try {
        check.tracker.moveToStatus(ticketKey, check.backlogStatus);
    } catch (e) {
        console.warn('Failed to move ticket to Backlog:', e.message || e);
        return moveFailed(e);
    }

    try {
        check.tracker.postComment(ticketKey, unblockComment(check.blockers));
        console.log('✅ Posted unblock comment to Jira');
    } catch (e) {
        console.warn('Failed to post comment:', e.message || e);
    }

    console.log('✅ Moved', ticketKey, 'to Backlog');

    // Post token usage summary comments (e.g. [story_acceptance_criteria]: {...}) if any provider
    // wrote outputs/*_usage.json during the agent run.
    try {
        tokenUsageComment.postTokenUsageComments(ticketKey, { initiator: params.initiator, customParams: tokenUsageComment.customParamsOf(params) });
    } catch (e) {
        console.warn('Failed to post token usage comments:', e);
    }

    return { success: true, action: 'moved_to_backlog', blockersResolved: check.blockers.length, ticketKey: ticketKey };
}

function action(params) {
    var ticketKey = ticketKeyOf(params);
    if (!ticketKey) {
        console.error('No ticket key provided');
        return { success: false, action: 'missing_ticket' };
    }

    var check = checkBlockers(params, ticketKey);
    if (check.error) {
        return check.error;
    }

    if (check.unresolved) {
        console.log('Still blocked by', check.unresolved.length, 'unresolved ticket(s):', unresolvedKeysText(check.unresolved));
        return { success: true, action: 'still_blocked', unresolved: check.unresolved, ticketKey: ticketKey };
    }

    if (check.blockers.length === 0) {
        return unblockWithoutBlockers(check, ticketKey);
    }
    return unblockAllResolved(check, ticketKey, params);
}

if (typeof module !== 'undefined' && module.exports) {
    module.exports = { action };
}

/**
 * redirectToRepoAgent.js
 * preJSAction for story_development_redirect*.json
 *
 * Extracts [repo] from ticket summary, then runs:
 *   dmtools run "{repo}/{targetAgentName}" --inputJql "key={ticketKey}" --debug
 *
 * customParams.targetAgentName controls which agent to delegate to
 * (e.g. "story_development.json" or "story_development_test.json").
 *
 * IMPORTANT: --debug is required here. Without it, dmtools' launcher selects
 * log4j2-cli.xml (Root level OFF) for this nested process, which silently
 * discards EVERY java-side logger.info()/warn() call — including
 * CliExecutionHelper's "Executing CLI command: ..." announcement and, more
 * importantly, CommandLineUtils.runCommand()'s real-time streaming of the
 * actual CLI agent's (Copilot/etc.) own stdout via logger.info(line). Only
 * plain JS console.log() calls (which bypass log4j, writing straight to
 * System.out) would have survived — making it look like the CLI agent never
 * ran at all, when it may well have, just with zero visibility.
 *
 * Returns false to abort own processing — target agent handles everything.
 */


// Tracker-agnostic ticket operations (jira / ado / github) — created lazily per action() run.
var trackersModule = require('./common/trackers.js');
var _trackerCtx = { config: null, customParams: {} };
var _trackerInst = null;
function initTracker(config, customParams) {
    _trackerCtx = { config: config || null, customParams: customParams || {} };
    _trackerInst = null;
}
function getTracker() {
    if (!_trackerInst) _trackerInst = trackersModule.createTracker(_trackerCtx.config, _trackerCtx.customParams);
    return _trackerInst;
}

// ── pure parse/build helpers (CRAP gate: each ≤ 8) ──────────────────────────

// Last path segment of the input folder — the ticket key container.
function folderKey(folder) {
    return (folder || '').split('/').pop() || '';
}

// customParams as seen by this action: jobParams win, then the params body.
function customParamsOf(params, actualParams) {
    return (params.jobParams && params.jobParams.customParams) || actualParams.customParams || {};
}

// CI run URL forwarded to the target agent for ticket↔run tracing.
function ciRunUrlOf(params, actualParams) {
    return actualParams.ciRunUrl || params.ciRunUrl || (params.jobParams && params.jobParams.ciRunUrl) || '';
}

// Everything action() needs to know about the incoming dmtools params.
function resolveRunScope(params) {
    var actualParams = params.inputFolderPath ? params : (params.jobParams || params);
    var customParams = customParamsOf(params, actualParams);
    return {
        actualParams: actualParams,
        folder: actualParams.inputFolderPath || '',
        customParams: customParams,
        targetAgentName: customParams.targetAgentName || 'story_development.json',
        agentsDir: customParams.repoAgentsDir || 'repo-agents',
        ciRunUrl: ciRunUrlOf(params, actualParams)
    };
}

// Ticket key: the ticket itself is authoritative, the folder is the fallback.
function ticketKeyOf(ticket, folder) {
    return (ticket && ticket.key) ? ticket.key : folderKey(folder);
}

// Summary string of a fetched ticket, '' when the shape is unexpected.
function summaryOf(ticket) {
    return (ticket && ticket.fields && ticket.fields.summary)
        ? ticket.fields.summary.toString()
        : '';
}

// [repo] tag parsed from the summary — null when absent or malformed.
function repoTagOf(summary) {
    if (!summary || summary.charAt(0) !== '[') return null;
    var bracketEnd = summary.indexOf(']');
    if (bracketEnd === -1) return null;
    return summary.substring(1, bracketEnd).trim();
}

// The nested dmtools run command (— --debug keeps java-side logging visible).
function buildRunCommand(agent, ticketKey, ciRunUrl) {
    var command = 'dmtools --debug run "' + agent + '" --inputJql "key=' + ticketKey + '"';
    if (ciRunUrl) {
        command += ' --ciRunUrl "' + ciRunUrl + '"';
    }
    return command;
}

function action(params) {
    var scope = resolveRunScope(params);
    initTracker(null, scope.customParams);

    var ticket = params.ticket || scope.actualParams.ticket;
    if (!ticket || !ticket.fields) {
        try {
            ticket = getTracker().getIssue(folderKey(scope.folder));
        } catch (e) {
            console.error('redirectToRepoAgent: could not fetch ticket: ' + e);
            return false;
        }
    }

    var ticketKey = ticketKeyOf(ticket, scope.folder);
    var summary = summaryOf(ticket);
    var repoName = repoTagOf(summary);
    if (!repoName) {
        console.error('redirectToRepoAgent: no [repo] tag found in summary: "' + summary + '"');
        return false;
    }
    var agent = scope.agentsDir + '/' + repoName + '/' + scope.targetAgentName;

    console.log('redirectToRepoAgent: ' + ticketKey + ' \u2192 ' + agent);

    try {
        cli_execute_command({ command: buildRunCommand(agent, ticketKey, scope.ciRunUrl) });
    } catch (e) {
        console.error('redirectToRepoAgent: failed to run ' + agent + ': ' + e);
        return false;
    }

    return false;
}

if (typeof module !== 'undefined') {
    module.exports = { action: action };
}

/**
 * Fetch Epics To Input Pre-CLI Action
 * Fetches existing epics and writes them to the input folder before CLI agent runs.
 * Receives params.inputFolderPath from DMTools after input folder creation.
 */

/**
 * Pre-CLI action: fetch existing epics into input folder
 *
 * @param {Object} params - Parameters from DMTools
 * @param {string} params.inputFolderPath - Path to the input folder for this run
 */

// Load-time require (gh-823): a deferred require would resolve against the
// pack js/ root only — hoist every require to the top of the module.
var trackersModule = require("./common/trackers.js");

/**
 * Find a field value by partial key name (handles "Display Name (customfieldXXX)" keys).
 */
function findField(fields, nameSubstring) {
    for (var key in fields) {
        if (key.indexOf(nameSubstring) !== -1) {
            return fields[key];
        }
    }
    return null;
}

// ── pure parse/build helpers (CRAP gate: each ≤ 8) ──────────────────────────

// Last path segment of the input folder — the ticket key container.
function folderKeyOf(folder) {
    return folder ? folder.split('/').pop() : '';
}

// Jira project part of a ticket key (everything before the first dash).
function projectOf(ticketKey) {
    return ticketKey ? ticketKey.split('-')[0] : '';
}

// customParams as seen by this action: jobParams win, then the params body.
function createTrackerFor(params) {
    return trackersModule.createTracker(null, (params.jobParams && params.jobParams.customParams) || params.customParams || {});
}

function priorityNameOf(fields) {
    return fields.priority ? fields.priority.name : '';
}

function parentKeyOf(fields) {
    return fields.parent ? fields.parent.key : null;
}

function statusNameOf(fields) {
    return fields.status ? fields.status.name : '';
}

// "Acceptance Criteria" first, legacy "Acceptance Criterias" spelling second.
function acceptanceCriteriaOf(fields) {
    return findField(fields, 'Acceptance Criteria') || findField(fields, 'Acceptance Criterias') || null;
}

// Epic summary shape written to existing_epics.json.
function mapEpic(issue) {
    var f = issue.fields || {};
    return {
        key: issue.key || '',
        summary: f.summary || '',
        description: f.description || '',
        priority: priorityNameOf(f),
        diagrams: f['Diagrams (customfield_10296)'] || f.Diagrams || null,
        parent: parentKeyOf(f)
    };
}

// Story summary shape written to existing_stories.json.
function mapStory(issue) {
    var sf = issue.fields || {};
    return {
        key: issue.key || '',
        summary: sf.summary || '',
        description: sf.description || '',
        status: statusNameOf(sf),
        priority: priorityNameOf(sf),
        diagrams: findField(sf, 'Diagrams') || null,
        acceptanceCriteria: acceptanceCriteriaOf(sf),
        solution: findField(sf, 'Solution') || null,
        parent: parentKeyOf(sf)
    };
}

// Static-analysis hooks (docs-freshness): agentDocGenerator discovers written
// artifacts with literal-path regexes, so each family keeps its concrete file
// name inside the file_write call — a dynamic spec.fileName path would
// collapse the generated "Writes" list to input/<KEY>/ and red the
// docs-freshness CI (pinned in test_configLoader.js).
function writeEpicsFile(folder, payload) {
    file_write(folder + '/existing_epics.json', payload);
}

function writeStoriesFile(folder, payload) {
    file_write(folder + '/existing_stories.json', payload);
}

// Search spec for one issue family (provider-specific query: WIQL on ado).
function epicSpec(project) {
    return {
        jql: 'project = ' + project + ' AND issuetype = Epic ORDER BY created DESC',
        fields: ['key', 'summary', 'description', 'priority', 'parent'],
        map: mapEpic,
        listKey: 'epics',
        fileName: 'existing_epics.json',
        writeFile: writeEpicsFile,
        plural: 'epics',
        brokenLabel: 'Failed to fetch epic'
    };
}

function storySpec(project) {
    return {
        jql: 'project = ' + project + ' AND issuetype = Story ORDER BY created DESC',
        fields: ['key', 'summary', 'status', 'priority', 'parent'],
        map: mapStory,
        listKey: 'stories',
        fileName: 'existing_stories.json',
        writeFile: writeStoriesFile,
        plural: 'stories',
        brokenLabel: 'Failed to fetch story'
    };
}

// Re-fetch every found issue (full field set) and map it; one broken fetch is
// skipped with a log line, the rest still land in the file.
function collectMappedIssues(tracker, spec) {
    var rawIssues = tracker.searchIssues(spec.jql, { fields: spec.fields });
    var issues = [];
    for (var i = 0; i < rawIssues.length; i++) {
        try {
            issues.push(spec.map(tracker.getIssue(rawIssues[i].key)));
        } catch (e) {
            console.error(spec.brokenLabel + ' ' + rawIssues[i].key + ':', e);
        }
    }
    return issues;
}

// Search → map → write one existing_*.json payload; a fetch failure is logged
// and the run continues without the file.
function fetchAndWrite(tracker, folder, spec) {
    try {
        var issues = collectMappedIssues(tracker, spec);
        console.log('Found ' + issues.length + ' ' + spec.plural);
        spec.writeFile(folder, '{"' + spec.listKey + '":' + JSON.stringify(issues, null, 2) + '}');
        console.log('Wrote ' + spec.fileName + ' to ' + folder);
    } catch (fetchError) {
        console.error('Failed to fetch ' + spec.plural + ', continuing without file:', fetchError);
    }
}

function action(params) {
    try {
        const folder = params.inputFolderPath;
        var ticketKey = folderKeyOf(folder);
        var project = projectOf(ticketKey);
        var tracker = createTrackerFor(params);
        console.log('Fetching existing epics for project ' + project + '...');

        fetchAndWrite(tracker, folder, epicSpec(project));
        fetchAndWrite(tracker, folder, storySpec(project));
    } catch (error) {
        console.error('Error in fetchEpicsToInput:', error);
    }
}

if (typeof module !== "undefined" && module.exports) {
    module.exports = { action, findField };
}

/**
 * Intake Pre-Action
 * 1. Checks for WIP label (returns false to stop processing if found)
 * 2. Fetches existing epics and writes them into the input folder
 *    (file_write creates parent dirs, so this runs before dmtools creates input/<KEY>/)
 */

var trackersModule = require('./common/trackers.js');

// ── pure parse/build helpers (CRAP gate: each ≤ 8) ──────────────────────────

// customParams as seen by this action: jobParams win, then the params body.
function createTrackerFor(params) {
    return trackersModule.createTracker(null, (params.jobParams && params.jobParams.customParams) || params.customParams || {});
}

function priorityNameOf(fields) {
    return fields.priority ? fields.priority.name : '';
}

function parentKeyOf(fields) {
    return fields.parent ? fields.parent.key : null;
}

function statusNameOf(fields) {
    return fields.status ? fields.status.name : '';
}

// The WIP label of this agent's context when present on the ticket, null
// otherwise (including when there is no contextId to derive one from).
function wipLabelOn(ticket, metadata) {
    if (!(metadata && metadata.contextId)) {
        console.log('No contextId in metadata, skipping WIP check');
        return null;
    }
    var wipLabel = metadata.contextId + '_wip';
    var labels = ticket.fields && ticket.fields.labels ? ticket.fields.labels : [];

    return labels.includes(wipLabel) ? wipLabel : null;
}

// Best-effort skip notice — a comment failure must not change the outcome.
function postSkipComment(tracker, ticketKey, wipLabel) {
    try {
        tracker.postComment(ticketKey, 'h3. *Processing Skipped*\n\n' +
            'This ticket has the *' + wipLabel + '* label indicating work is in progress.\n' +
            'Processing will be skipped until the label is removed.\n\n' +
            '_Remove the label to allow automated processing._');
    } catch (e) {
        console.warn('Failed to post skip comment:', e);
    }
}

// Epic summary shape written to existing_epics.json (from raw search results).
function mapEpic(issue) {
    var f = issue.fields || {};
    return {
        key: issue.key || '',
        summary: f.summary || '',
        description: f.description || '',
        priority: priorityNameOf(f),
        diagrams: f.diagrams || null,
        parent: parentKeyOf(f)
    };
}

// Story summary shape written to existing_stories.json (raw search results).
function mapStory(issue) {
    var sf = issue.fields || {};
    return {
        key: issue.key || '',
        summary: sf.summary || '',
        status: statusNameOf(sf),
        priority: priorityNameOf(sf),
        diagrams: sf.diagrams || null,
        parent: parentKeyOf(sf)
    };
}

// Static-analysis hooks (docs-freshness): agentDocGenerator discovers written
// artifacts with literal-path regexes, so each family keeps its concrete file
// name inside the file_write call — a dynamic spec.fileName path would
// collapse the generated "Writes" list to input/<KEY>/ and red the
// docs-freshness CI (pinned in test_configLoader.js).
function writeEpicsFile(inputFolder, payload) {
    file_write(inputFolder + '/existing_epics.json', payload);
}

function writeStoriesFile(inputFolder, payload) {
    file_write(inputFolder + '/existing_stories.json', payload);
}

// Search spec for one issue family (provider-specific query: WIQL on ado).
function epicSpec(project) {
    return {
        jql: 'project = ' + project + ' AND issuetype = Epic ORDER BY created DESC',
        fields: ['key', 'summary', 'description', 'priority', 'diagrams', 'parent'],
        map: mapEpic,
        listKey: 'epics',
        fileName: 'existing_epics.json',
        writeFile: writeEpicsFile,
        plural: 'epics'
    };
}

function storySpec(project) {
    return {
        jql: 'project = ' + project + ' AND issuetype = Story ORDER BY created DESC',
        fields: ['key', 'summary', 'status', 'priority', 'diagrams', 'parent'],
        map: mapStory,
        listKey: 'stories',
        fileName: 'existing_stories.json',
        writeFile: writeStoriesFile,
        plural: 'stories'
    };
}

// Search → map (straight off the search results, no per-issue fetch) → write.
// A fetch failure is logged and the run continues without the file.
function fetchAndWrite(tracker, inputFolder, spec) {
    try {
        var issues = tracker.searchIssues(spec.jql, { fields: spec.fields }).map(spec.map);
        console.log('Found ' + issues.length + ' ' + spec.plural);
        spec.writeFile(inputFolder, '{"' + spec.listKey + '":' + JSON.stringify(issues, null, 2) + '}');
        console.log('Wrote ' + spec.fileName + ' to ' + inputFolder);
    } catch (fetchError) {
        console.error('Failed to fetch ' + spec.plural + ', continuing without file:', fetchError);
    }
}

function action(params) {
    try {
        var ticket = params.ticket;
        var ticketKey = ticket.key;
        var tracker = createTrackerFor(params);

        // --- WIP label check ---
        var wipLabel = wipLabelOn(ticket, params.metadata);
        if (wipLabel) {
            console.log('Ticket ' + ticketKey + ' has WIP label "' + wipLabel + '" - skipping');
            postSkipComment(tracker, ticketKey, wipLabel);
            return false;
        }

        // --- Fetch existing epics into input folder ---
        // file_write creates parent directories automatically,
        // so this works even before dmtools creates input/<KEY>/
        var inputFolder = 'input/' + ticketKey;
        var project = ticketKey.split('-')[0];
        console.log('Fetching existing epics for ' + ticketKey + '...');

        fetchAndWrite(tracker, inputFolder, epicSpec(project));
        fetchAndWrite(tracker, inputFolder, storySpec(project));

        return true;

    } catch (error) {
        console.error('Error in intakePreAction:', error);
        return true; // don't block on unexpected error
    }
}

if (typeof module !== 'undefined' && module.exports) {
    module.exports = { action: action };
}

