            if (opts.cliThrows) throw new Error('cli exploded');
            return 'done';
        }
    };

    var mod = loadModule(
        'js/redirectToRepoAgent.js',
        makeRequire({ './common/trackers.js': trackersMock }),
        globalMocks
    );

    return { mod: mod, calls: calls };
}

