}

// Scripted searchIssues outcome for one JQL: results list, or a thrown error.
function searchResultsFor(opts, jql) {
    var spec = (opts.searchResults || {})[jql];
    if (spec && spec.throwOnSearch) throw new Error('search down: ' + jql);
