    console.log('All', check.blockers.length, 'blocker(s) resolved — moving', ticketKey, 'to Backlog');
    try {
        check.tracker.moveToStatus(ticketKey, check.backlogStatus);
    } catch (e) {
        console.warn('Failed to move ticket to Backlog:', e.message || e);
        return moveFailed(e);
    }

    try {
