// The nested dmtools run command (— --debug keeps java-side logging visible).
function buildRunCommand(agent, ticketKey, ciRunUrl) {
    var command = 'dmtools --debug run "' + agent + '" --inputJql "key=' + ticketKey + '"';
    if (ciRunUrl) {
