}

function action(params) {
    var ticketKey = ticketKeyOf(params);
    if (!ticketKey) {
        console.error('No ticket key provided');
        return { success: false, action: 'missing_ticket' };
    }

    var check = checkBlockers(params, ticketKey);
    if (check.error) {
