        fetchAndWrite(tracker, inputFolder, epicSpec(project));
        fetchAndWrite(tracker, inputFolder, storySpec(project));

        return true;

    } catch (error) {
        console.error('Error in intakePreAction:', error);
        return true; // don't block on unexpected error
    }
}

