        } catch (e) {
            console.error('redirectToRepoAgent: could not fetch ticket: ' + e);
            return false;
        }
    }

    var ticketKey = ticketKeyOf(ticket, scope.folder);
    var summary = summaryOf(ticket);
    var repoName = repoTagOf(summary);
