                                summary: 'Epic one',
                                description: 'Desc',
                                priority: { name: 'High' },
                                diagrams: 'diag-1',
                                parent: { key: 'PROJ-1' }
                            }
                        },
                        { key: 'PROJ-11', fields: { summary: 'Epic two' } }
                    ]
                };
                m[STORY_JQL] = {
                    results: [
                        {
                            key: 'PROJ-20',
                            fields: {
                                summary: 'Story one',
                                status: { name: 'To Do' },
                                priority: { name: 'Low' },
                                diagrams: 'diag-2',
                                parent: { key: 'PROJ-10' }
                            }
                        }
                    ]
                };
                return m;
            })()
        });

        var result = loaded.mod.action(intakeParams());

        assert.equal(result, true, 'processing continues after the pre-action');
        assert.deepEqual(loaded.calls.search, [
