    });

    test('ciRunUrl resolution order: params.ciRunUrl also accepted, absent means no flag', function () {
        var loaded = loadRedirectToRepoAgent({});
        loaded.mod.action({
            ticket: { key: 'PROJ-6', fields: { summary: '[a] b' } },
