        });

        assert.deepEqual(loaded.calls.cli, [
            { command: 'dmtools --debug run "repo-agents/a/story_development.json" --inputJql "key=PROJ-6" --ciRunUrl "https://ci.example.com/run/7"' }
        ]);

        var plain = loadRedirectToRepoAgent({});
        plain.mod.action({
