function ticketBlockedBy(statusName) {
    return {
        fields: {
            issuelinks: [
                {
                    type: { name: 'Blocks' },
                    inwardIssue: { key: 'PROJ-1', fields: { status: { name: statusName } } }
                }
            ]
        }
    };
}

suite('unblockResolvedDependencies', function() {

